      html += '<div class="msg-row ' + (mine ? "mine" : "") + '" data-mid="' + esc(m.id) + '">' + (!mine && r.type === "group" ? '<span data-pp="' + esc(m.from) + '" style="cursor:pointer;align-self:flex-end">' + avatar(p, 30, false) + "</span>" : "") + '<div style="min-width:0">' + (showName ? '<div class="msg-group-name" data-pp="' + esc(m.from) + '" style="cursor:pointer">' + esc(p.name) + "</div>" : "") + '<div class="bubble">' + body + '<div class="meta">' + fmtTime(m.at) + (mine ? " ✓✓" : "") + "</div>" + rx + "</div></div></div>";
