      const t = $("#gsToggle", m); if (t) t.onclick = () => { gs.active = !gs.active; if (!gs.active) gs.schedule.enabled = false; r.messages.push({ id: uid(), from: "system", kind: "system", text: gs.active ? "🎙 Instant speech session STARTED by " + S.me.name + "." : "🔇 Instant speech session ENDED by " + S.me.name + ".", at: NOW() }); refresh(); };
