      $("#leaveGrp", m).onclick = () => { if (!confirm("Leave " + roomTitle(r) + "?")) return; S.rooms = S.rooms.filter((x) => x.id !== r.id); closeModal(); location.hash = "#/chat"; toast("You left " + roomTitle(r) + " (demo)."); };
